    "answer": "在python中可以使用isinstance()函数来判断数据类型，isinstance()函数来判断一个对象是否是一个已知的类型，类似 type()。\nisinstance() 与 type() 区别：\ntype() 不会认为子类是一种父类类型，不考虑继承关系。isinstance() 会认为子类是一种父类类型，考虑继承关系。如果要判断两个类型是否相同推荐使用 isinstance()。",
