    "answer": "def hanoi(n, a, b, c):\n    if n == 1:                     # 只剩一个盘子，直接搬\n        print(a, \"->\", c)\n        return\n    hanoi(n - 1, a, c, b)          # 上面 n-1 个先搬到辅助柱\n    print(a, \"->\", c)              # 最大的那个搬到目标柱\n    hanoi(n - 1, b, a, c)          # 辅助柱上的 n-1 个搬到目标柱\n\nhanoi(3, \"A\", \"B\", \"C\")",
